"""This file contains the Sim Dialogs Main Start, Stop and ASU Buttons Page Object class for the
Main Buttons pane in the Sim Dialogs XVI test tool"""

import logging
from . import SimDialogs
from .. interactions import SimDialogMainFuncs


logger = logging.getLogger(__name__)

class SimDialogsMainButtons(SimDialogs):
    ''' Page Object class for the Main Start, Stop and ASU buttons pane'''

    def __init__(self, host_address: str ="192.168.30.4") -> None:
        super().__init__(host_address)

    def select_main_sim_dialogs_start_button(self) -> None:
        '''Clicks the main Start button on the Sim Dialogs window'''
        SimDialogMainFuncs.click_main_sim_dialogs_start_button()

    def select_main_sim_dialogs_stop_button(self) -> None:
        '''Clicks the main Stop button on the Sim Dialogs window'''
        SimDialogMainFuncs.click_main_sim_dialogs_stop_button()

    def select_main_sim_dialogs_asu_button(self) -> None:
        '''Clicks the main ASU button on the Sim Dialogs window'''
        SimDialogMainFuncs.click_main_sim_dialogs_asu_button()

